// This file is generated by AI.

// 多选项卡栏: 每个打开的场景/文件、文本预处理、差异比较、配音总控台/帮助各对应一个选项卡。
// 支持拖拽调整顺序 (基于 Pointer 事件: HTML5 DnD 在部分 WebView 中不可靠)。
//
// 场景选项卡最左侧有一个麦克风按钮 (配音模式开关): 带斜杠表示未启动配音模式。
// 配音卡 (已启动) 恒显示该按钮, 普通场景卡仅在选中时显示, 以免未选中时干扰。
// 按钮的提示文本使用原生 title, 与项目其余部分保持一致。

import { useRef, useState } from 'react';

import {
  ArrowSwapRegular,
  BookQuestionMarkRegular,
  DocumentTextRegular,
  MicProhibitedRegular,
  MicRegular,
} from '@fluentui/react-icons';

import { disposeModel } from '../lsp/monaco';
import { disposeNovelTab } from '../novel/registry';
import { useAppStore } from '../state/store';
import { confirmClose } from '../unsaved';
import { voiceController } from '../voice/controller';
import { FileBadges } from './FileBadges';

/** 指针水平位移超过该阈值才判定为拖拽, 避免与点击选中冲突 */
const DRAG_THRESHOLD = 6;

export function EditorTabs() {
  const documents = useAppStore((s) => s.documents);
  const activePath = useAppStore((s) => s.activePath);
  const setActiveDocument = useAppStore((s) => s.setActiveDocument);
  const closeDocument = useAppStore((s) => s.closeDocument);
  const moveDocument = useAppStore((s) => s.moveDocument);
  const novelTabs = useAppStore((s) => s.novelTabs);
  const activeNovelId = useAppStore((s) => s.activeNovelId);
  const setActiveNovel = useAppStore((s) => s.setActiveNovel);
  const closeNovelTab = useAppStore((s) => s.closeNovelTab);
  const diffTabs = useAppStore((s) => s.diffTabs);
  const activeDiffId = useAppStore((s) => s.activeDiffId);
  const setActiveDiff = useAppStore((s) => s.setActiveDiff);
  const closeDiffTab = useAppStore((s) => s.closeDiffTab);
  const guidanceTabs = useAppStore((s) => s.guidanceTabs);
  const activeGuidanceId = useAppStore((s) => s.activeGuidanceId);
  const setActiveGuidance = useAppStore((s) => s.setActiveGuidance);
  const closeGuidanceTab = useAppStore((s) => s.closeGuidanceTab);
  const voiceMode = useAppStore((s) => s.voiceModePaths);
  const setVoiceMode = useAppStore((s) => s.setVoiceMode);
  const voiceConsoleOpen = useAppStore((s) => s.voiceConsoleOpen);
  const setVoiceConsoleOpen = useAppStore((s) => s.setVoiceConsoleOpen);
  const queuePending = useAppStore((s) => s.voiceQueuePending);

  const containerRef = useRef<HTMLDivElement>(null);
  // 拖拽过程中的临时状态 (非渲染状态放 ref, 避免频繁重渲染)
  const dragState = useRef<{ path: string; startX: number; active: boolean } | null>(null);
  const [draggingPath, setDraggingPath] = useState<string | null>(null);
  const [dropIndex, setDropIndex] = useState<number | null>(null);

  /** 命中检测: 返回指针 x 坐标所在的选项卡下标。 */
  const hitTest = (clientX: number): number => {
    const tabs = containerRef.current?.querySelectorAll<HTMLElement>('.editor-tab');
    const container = containerRef.current;
    if (!tabs || !container || tabs.length === 0) return -1;
    for (let i = 0; i < tabs.length; i++) {
      const rect = tabs[i].getBoundingClientRect();
      if (clientX >= rect.left && clientX <= rect.right) return i;
    }
    if (clientX < container.getBoundingClientRect().left) return 0;
    return tabs.length;
  };

  const onPointerDown = (e: React.PointerEvent<HTMLDivElement>, path: string) => {
    if (e.button !== 0) return; // 仅左键
    if ((e.target as HTMLElement).closest('.editor-tab-close')) return; // 关闭按钮不触发拖拽
    if ((e.target as HTMLElement).closest('.editor-tab-voice')) return; // 麦克风按钮不触发拖拽
    dragState.current = { path, startX: e.clientX, active: false };
    e.currentTarget.setPointerCapture(e.pointerId);
  };

  const onPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const state = dragState.current;
    if (!state) return;
    if (!state.active) {
      if (Math.abs(e.clientX - state.startX) < DRAG_THRESHOLD) return;
      state.active = true;
      setDraggingPath(state.path);
    }
    setDropIndex(hitTest(e.clientX));
  };

  const endDrag = (e: React.PointerEvent<HTMLDivElement>) => {
    const state = dragState.current;
    if (state?.active) {
      const target = hitTest(e.clientX);
      if (target >= 0) moveDocument(state.path, target);
    }
    dragState.current = null;
    setDraggingPath(null);
    setDropIndex(null);
  };

  if (
    documents.length === 0 &&
    novelTabs.length === 0 &&
    diffTabs.length === 0 &&
    guidanceTabs.length === 0 &&
    !voiceConsoleOpen
  ) {
    return null;
  }

  /** 关闭场景选项卡: 有未完成的配音任务时先询问 */
  const closeSceneTab = (path: string) => {
    const finish = () => {
      voiceController.closeCard(path);
      disposeModel(path);
      closeDocument(path);
    };
    if (voiceController.hasUnfinished(path)) {
      if (!window.confirm('该场景还有未完成的配音任务，关闭后这些任务将丢失。仍要关闭吗？')) return;
    }
    confirmClose(finish, path);
  };

  return (
    <div className="editor-tabs" role="tablist" ref={containerRef}>
      {documents.map((d, index) => {
        const inVoiceMode = voiceMode.includes(d.path);
        return (
          <div
            key={d.path}
            role="tab"
            aria-selected={d.path === activePath}
            className={`editor-tab${d.path === activePath ? ' active' : ''}${draggingPath === d.path ? ' dragging' : ''}${
              dropIndex === index && draggingPath !== d.path ? ' drop-target' : ''
            }${dropIndex === documents.length && index === documents.length - 1 && draggingPath !== d.path ? ' drop-target-end' : ''}${
              inVoiceMode ? ' voice' : ''
            }`}
            onClick={() => setActiveDocument(d.path)}
            onPointerDown={(e) => onPointerDown(e, d.path)}
            onPointerMove={onPointerMove}
            onPointerUp={endDrag}
            onPointerCancel={endDrag}
            title={d.path}
          >
            {/*
              配音模式指示与切换, 放在最左侧。
              配音卡恒显示 (未选中也显示), 普通场景卡仅在选中时显示 —— 未选中时无需干扰。
              提示文本统一使用原生的 title 属性, 与项目其余部分保持一致。
            */}
            {(inVoiceMode || d.path === activePath) && (
              <button
                className={`editor-tab-voice${inVoiceMode ? ' on' : ''}`}
                title={inVoiceMode ? '退出配音模式' : '进入配音模式'}
                onClick={(e) => {
                  e.stopPropagation();
                  if (!inVoiceMode) setActiveDocument(d.path);
                  setVoiceMode(d.path, !inVoiceMode);
                }}
              >
                {inVoiceMode ? <MicRegular /> : <MicProhibitedRegular />}
              </button>
            )}

            <span className="editor-tab-name">
              {d.dirty ? <span className="dirty-dot">●</span> : null}
              {d.name}
              <FileBadges path={d.path} />
            </span>

            <button
              className="editor-tab-close"
              title="关闭"
              onClick={(e) => {
                e.stopPropagation();
                closeSceneTab(d.path);
              }}
            >
              ×
            </button>
          </div>
        );
      })}
      {novelTabs.map((t) => (
        <div
          key={t.id}
          role="tab"
          aria-selected={t.id === activeNovelId}
          className={`editor-tab novel${t.id === activeNovelId ? ' active' : ''}`}
          onClick={() => setActiveNovel(t.id)}
          title={t.title}
        >
          <span className="editor-tab-name">
            <span className="editor-tab-icon">
              <DocumentTextRegular />
            </span>
            {t.title}
          </span>
          <button
            className="editor-tab-close"
            title="关闭"
            onClick={(e) => {
              e.stopPropagation();
              disposeNovelTab(t.id);
              closeNovelTab(t.id);
            }}
          >
            ×
          </button>
        </div>
      ))}
      {diffTabs.map((t) => (
        <div
          key={t.id}
          role="tab"
          aria-selected={t.id === activeDiffId}
          className={`editor-tab diff${t.id === activeDiffId ? ' active' : ''}`}
          onClick={() => setActiveDiff(t.id)}
          title={t.file}
        >
          <span className="editor-tab-name">
            <span className="editor-tab-icon">
              <ArrowSwapRegular />
            </span>
            {t.title}
          </span>
          <button
            className="editor-tab-close"
            title="关闭"
            onClick={(e) => {
              e.stopPropagation();
              closeDiffTab(t.id);
            }}
          >
            ×
          </button>
        </div>
      ))}
      {/*
        配音总控台也是一个选项卡 (与预处理/差异比较一致), 渲染顺序紧邻其它工具选项卡。
        关闭它即退出"全局配音模式"。
      */}
      {voiceConsoleOpen && (
        <div role="tab" aria-selected className="editor-tab console active" title="配音总控台">
          <span className="editor-tab-name">
            <span className="editor-tab-icon">
              <MicRegular />
            </span>
            配音总控台
            {queuePending > 0 && <span className="editor-tab-badge">{queuePending}</span>}
          </span>
          <button
            className="editor-tab-close"
            title="关闭"
            onClick={(e) => {
              e.stopPropagation();
              setVoiceConsoleOpen(false);
            }}
          >
            ×
          </button>
        </div>
      )}
      {guidanceTabs.map((t) => (
        <div
          key={t.id}
          role="tab"
          aria-selected={t.id === activeGuidanceId}
          className={`editor-tab help${t.id === activeGuidanceId ? ' active' : ''}`}
          onClick={() => setActiveGuidance(t.id)}
          title={t.title}
        >
          <span className="editor-tab-name">
            <span className="editor-tab-icon">
              <BookQuestionMarkRegular />
            </span>
            {t.title}
          </span>
          <button
            className="editor-tab-close"
            title="关闭"
            onClick={(e) => {
              e.stopPropagation();
              closeGuidanceTab(t.id);
            }}
          >
            ×
          </button>
        </div>
      ))}
    </div>
  );
}
